import{_ as e,o as d,c as a,a8 as o}from"./chunks/framework.BppdKxCY.js";const u=JSON.parse('{"title":"113 Vue 3 单仓多端工程","description":"","frontmatter":{"title":"113 Vue 3 单仓多端工程"},"headers":[],"relativePath":"113-vue3-multi-end.md","filePath":"113-vue3-multi-end.md","lastUpdated":1793706365000}'),r={name:"113-vue3-multi-end.md"};function c(l,t,i,s,h,n){return d(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="第一百一十三部分-·-vue-3-单仓多端工程——pc-web-h5-pwa-一体化" tabindex="-1">第一百一十三部分 · Vue 3 单仓多端工程——PC Web + H5/PWA 一体化 <a class="header-anchor" href="#第一百一十三部分-·-vue-3-单仓多端工程——pc-web-h5-pwa-一体化" aria-label="Permalink to &quot;第一百一十三部分 · Vue 3 单仓多端工程——PC Web + H5/PWA 一体化&quot;">​</a></h1><blockquote><p>🧭 <a href="./README">返回总目录</a>｜上一篇：<a href="./112-graphql-client">第一百一十二部分 · GraphQL 客户端实战——Schema、缓存与订阅</a>｜关联章节：<a href="./73-multi-end-architecture">第七十三部分 · 多端共用架构</a> · <a href="./88-uniapp-cross-platform">第八十八部分 · UniApp 跨端开发</a> · <a href="./56-offline-cache">第五十六部分 · 离线与本地缓存全景</a> · <a href="./102-element-plus-enterprise">第一百零二部分 · Element Plus / Vant 企业实战</a> · <a href="./09-testing">第九部分 · 测试策略</a></p></blockquote><h2 id="本部分内容" tabindex="-1">本部分内容 <a class="header-anchor" href="#本部分内容" aria-label="Permalink to &quot;本部分内容&quot;">​</a></h2><p>单仓多端的目标不是「少写一套页面」，而是<strong>同一份业务内核产出两个可独立发布、互不污染的产物</strong>：PC Web 要宽屏、鼠标、高信息密度；H5/PWA 要触控、窄屏、可安装、弱网可用。本册聚焦 Vue 3 + Vite 的落地：目录分层、构建矩阵、能力适配器、UI 分流、路由/状态复用、PWA 更新与双端 CI，目标业务复用 80%+、产物不串味。</p><hr><h2 id="_113-1-目标与复用率期望" tabindex="-1">113.1 目标与复用率期望 <a class="header-anchor" href="#_113-1-目标与复用率期望" aria-label="Permalink to &quot;113.1 目标与复用率期望&quot;">​</a></h2><h3 id="概念解析" tabindex="-1">概念解析 <a class="header-anchor" href="#概念解析" aria-label="Permalink to &quot;概念解析&quot;">​</a></h3><p>单仓多端是<strong>一个业务模型、两套表现层、两个发布物</strong>。端差异只应出现在 <code>adapters</code> 与 <code>ui-*</code>，泄漏到 <code>core</code> 会让业务规则分叉。复用率按层统计：</p><table tabindex="0"><thead><tr><th>层</th><th>内容</th><th>合理复用率</th><th>说明</th></tr></thead><tbody><tr><td><code>core</code> 领域层</td><td>定价、购物车、优惠、订单状态机</td><td>90%+</td><td>纯 TS，逐字节共享</td></tr><tr><td><code>services</code> 接口层</td><td>storage/share/payment 等契约</td><td>100%</td><td>只有类型与接口</td></tr><tr><td><code>composables</code></td><td>表单、列表、请求编排</td><td>70%~85%</td><td>端差异用能力接口抹平</td></tr><tr><td><code>ui-pc</code> / <code>ui-h5</code></td><td>页面、业务组件、交互</td><td>40%~70%</td><td>两套交互范式</td></tr><tr><td><code>adapters</code></td><td>端能力实现</td><td>≈0%</td><td>端端不同是设计目的</td></tr></tbody></table><p>真实场景：某海外 DTC 品牌的 Vue 3 商城，PC 承担商品对比、多步结账、地址簿；H5/PWA 承担投放页、一键结账与离线复购。两端共享定价、税费、优惠校验、购物车与订单状态机（约 80% 业务代码），UI 分别用 Element Plus 与 Vant。业务规则只改一处，UI 缺陷按端独立修。</p><p>反例：团队定下「复用率 95%」KPI，把 <code>ProductList.vue</code> 写成 <code>el-table</code> 与 <code>van-list</code> 双分支同时 import。H5 首屏 JS 从 210KB 涨到 320KB，CSS 变量互相覆盖；平板落入宽屏分支，得到小字号表格。运行时 <code>if</code> <strong>不会删除另一端的 import</strong>。</p><h3 id="应用实践" tabindex="-1">应用实践 <a class="header-anchor" href="#应用实践" aria-label="Permalink to &quot;应用实践&quot;">​</a></h3><ul><li>立项先定端角色：PC 做深度操作，H5 做消费与轻操作。</li><li>业务域抽到 <code>core</code>，交互域允许两端独立。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>✅ 复用率进 CI 报告（共享包被几个端 import），而不是喊口号。</li><li>✅ 第一天就分 <code>ui-pc</code> / <code>ui-h5</code>，后期拆目录成本远高于建目录。</li></ul><hr><h2 id="_113-2-目录与分层" tabindex="-1">113.2 目录与分层 <a class="header-anchor" href="#_113-2-目录与分层" aria-label="Permalink to &quot;113.2 目录与分层&quot;">​</a></h2><h3 id="概念解析-1" tabindex="-1">概念解析 <a class="header-anchor" href="#概念解析-1" aria-label="Permalink to &quot;概念解析&quot;">​</a></h3><p>按<strong>依赖方向</strong>切目录，而不是按页面切：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/</span></span>
<span class="line"><span>  core/              # 纯 TS 领域逻辑，零 Vue、零 DOM</span></span>
<span class="line"><span>  services/          # 能力接口：storage/share/payment</span></span>
<span class="line"><span>  adapters/pc|h5/    # 各自实现，可碰平台 API</span></span>
<span class="line"><span>  composables/       # 共享 Vue 逻辑，只依赖 core + services</span></span>
<span class="line"><span>  ui-shared/         # 无 UI 库依赖：价格、评分、空态</span></span>
<span class="line"><span>  ui-pc/             # Element Plus 页面与组件</span></span>
<span class="line"><span>  ui-h5/             # Vant 页面与组件</span></span>
<span class="line"><span>  router/  stores/   # 共享守卫、路由表、Pinia store</span></span>
<span class="line"><span>  apps/pc|h5/        # main.ts、index.*.html、manifest</span></span></code></pre></div><p>依赖铁律：<code>ui/composables → core/services</code>、<code>core → services</code>、<code>adapters → services</code>、<code>apps → 全部</code>。<code>core</code> 永不 import <code>adapters</code>，<code>ui-pc</code> 永不 import <code>ui-h5</code>。端能力通过接口注入：<code>core</code> 只声明「需要 storage」，由 <code>apps</code> 启动时放入实现。</p><p>为什么必须<strong>物理隔离</strong>？Code Review 拦不住「顺手 import 一个小工具」，一次顺手就可能把 Element Plus 拖进 H5 产物；目录隔离 + ESLint 才可靠。</p><h3 id="应用实践-1" tabindex="-1">应用实践 <a class="header-anchor" href="#应用实践-1" aria-label="Permalink to &quot;应用实践&quot;">​</a></h3><ul><li><code>@ui</code> 别名按 mode 指向 <code>ui-pc</code> 或 <code>ui-h5</code>，业务代码只写 <code>import X from &#39;@ui/views/ProductDetail.vue&#39;</code>。</li><li><code>services</code> 只放接口与错误类型，实现放 <code>adapters</code>，两端跑同一套契约测试。</li></ul><h3 id="最佳实践-1" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践-1" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>✅ ESLint 禁止 <code>ui-pc ↔ ui-h5</code>、<code>core → adapters</code>。</li><li>✅ <code>apps</code> 是唯一组装点：选 adapter、注入依赖、注册 UI 库。</li><li>⚠️ <code>ui-shared</code> 只放无交互范式的组件；带布局或手势的不要硬共享。</li></ul><hr><h2 id="_113-3-构建矩阵" tabindex="-1">113.3 构建矩阵 <a class="header-anchor" href="#_113-3-构建矩阵" aria-label="Permalink to &quot;113.3 构建矩阵&quot;">​</a></h2><h3 id="概念解析-2" tabindex="-1">概念解析 <a class="header-anchor" href="#概念解析-2" aria-label="Permalink to &quot;概念解析&quot;">​</a></h3><p>把 <strong>mode 当作唯一输入</strong>：一个 mode 决定环境变量、入口 HTML、产物目录、PWA 开关、体积预算与 UI 别名。禁止业务代码再用 <code>if (isPc)</code> 选入口，否则构建结果依赖运行时，CI 无法静态校验。</p><table tabindex="0"><thead><tr><th>mode</th><th>入口</th><th>产物</th><th>PWA</th><th>首屏 JS 预算（gzip）</th></tr></thead><tbody><tr><td><code>pc-dev</code></td><td><code>index.pc.html</code></td><td><code>dist/pc-dev</code></td><td>否</td><td>900KB</td></tr><tr><td><code>pc-prod</code></td><td><code>index.pc.html</code></td><td><code>dist/pc</code></td><td>否</td><td>520KB</td></tr><tr><td><code>h5-dev</code></td><td><code>index.h5.html</code></td><td><code>dist/h5-dev</code></td><td>否</td><td>520KB</td></tr><tr><td><code>h5-prod</code></td><td><code>index.h5.html</code></td><td><code>dist/h5</code></td><td>是</td><td>260KB</td></tr></tbody></table><p>只有 <code>VITE_</code> 前缀会暴露给客户端，<strong>密钥绝不能写进 <code>.env</code></strong>（见 66 册）。PWA 只在 <code>h5-prod</code> 开启；PC 装 SW 只会增加缓存排障成本。Vite 配置只需做三件事：<code>loadEnv</code> 读 mode、<code>@ui</code> 别名按端指向、<code>rollupOptions.input</code> 只放当前端入口。</p><p>产物校验不能只看「构建成功」：入口、预算、PWA 资源、串端依赖，每条都要成为 CI 硬门禁。完整实现见 <code>examples/113-02-build-matrix.ts</code>：<code>deriveTarget</code> 按 mode 推导，<code>validateBuild</code> 一次性返回全部违约项。</p><blockquote><p>运行方式：<code>npx tsx examples/113-02-build-matrix.ts</code></p></blockquote><h3 id="应用实践-2" tabindex="-1">应用实践 <a class="header-anchor" href="#应用实践-2" aria-label="Permalink to &quot;应用实践&quot;">​</a></h3><ul><li>CI 矩阵跑 <code>pc-prod</code> 与 <code>h5-prod</code>，各自上传 artifact；预览环境按端生成 URL。</li><li>产物一次构建、多区域 CDN 分发，不要按地区重复构建。</li><li>H5 面对弱网与低端机，预算必须比 PC 更紧；超预算直接 fail。</li></ul><h3 id="最佳实践-2" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践-2" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>✅ mode 名与产物目录一一对应，路径带端标识，避免部署拷错。</li><li>✅ 每端一个 HTML 入口，不要两端入口塞进同一次 <code>rollupOptions.input</code>。</li><li>⚠️ <code>.env.*.local</code> 进 <code>.gitignore</code>；CI 用环境变量注入真实配置。</li></ul><hr><h2 id="_113-4-端能力抽象与条件编译" tabindex="-1">113.4 端能力抽象与条件编译 <a class="header-anchor" href="#_113-4-端能力抽象与条件编译" aria-label="Permalink to &quot;113.4 端能力抽象与条件编译&quot;">​</a></h2><h3 id="概念解析-3" tabindex="-1">概念解析 <a class="header-anchor" href="#概念解析-3" aria-label="Permalink to &quot;概念解析&quot;">​</a></h3><p>端能力抽象 = <strong>接口 + 两套实现 + 一个组装点</strong>。接口只暴露 <code>end</code>、<code>storage</code>、<code>share</code>、<code>pay</code> 等最小能力，业务层只依赖接口。</p><p><code>adapters/pc</code> 用 Clipboard API 复制链接、二维码收银台；<code>adapters/h5</code> 优先 Web Share，失败降级复制，再失败给二维码；支付优先 App scheme，失败回落 hosted checkout。<strong>降级链写在 adapter 里</strong>。</p><table tabindex="0"><thead><tr><th>能力</th><th>PC 实现</th><th>H5 实现</th><th>降级</th></tr></thead><tbody><tr><td>storage</td><td>localStorage 5MB</td><td>WebView 64KB + 内存双写</td><td>容量失败返回 false</td></tr><tr><td>share</td><td>复制链接</td><td>Web Share → 复制 → 二维码</td><td>不阻断分享</td></tr><tr><td>pay</td><td>二维码收银台</td><td>App scheme → hosted checkout</td><td><code>fallbackUrl</code></td></tr></tbody></table><p>条件编译分两种：</p><ol><li><strong>构建期换实现（推荐）</strong>：<code>@adapters</code> 别名按 mode 指向 <code>adapters/pc</code> 或 <code>adapters/h5</code>，另一端代码不进产物。</li><li><strong>运行期分支（谨慎）</strong>：<code>if (import.meta.env.VITE_APP_END === &#39;pc&#39;)</code> 只决定执行路径，不删除 import。小差异可用，隔离 UI 库必然失败。</li></ol><p>端判定也不要只看 UA：<code>maxTouchPoints &gt; 0</code> 且视口窄归 H5，触摸但宽视口归 PC。完整实现见 <code>examples/113-01-capability-adapter.ts</code>：<code>detectEnd</code> 做能力判定，<code>createCapabilities</code> 组装 storage/share/payment 的端实现。</p><blockquote><p>运行方式：<code>npx tsx examples/113-01-capability-adapter.ts</code></p></blockquote><h3 id="应用实践-3" tabindex="-1">应用实践 <a class="header-anchor" href="#应用实践-3" aria-label="Permalink to &quot;应用实践&quot;">​</a></h3><ul><li><strong>存储</strong>：H5 WebView 的 localStorage 可能被系统清理，重要数据双写并接受容量失败返回值。</li><li><strong>分享</strong>：原生分享不可用时必须有复制/二维码兜底。</li><li><strong>支付</strong>：二维码、钱包、hosted checkout 三条路径都要有 <code>fallbackUrl</code>。</li></ul><h3 id="最佳实践-3" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践-3" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>✅ 接口返回结果对象（<code>{ channel, ok }</code>），不把平台异常抛给业务层。</li><li>✅ 两端 adapter 跑同一套契约测试，相同输入返回同构结构。</li><li>⚠️ <code>core</code> 不 import 任何 adapter；端判断属于外层知识。</li></ul><hr><h2 id="_113-5-ui-分流" tabindex="-1">113.5 UI 分流 <a class="header-anchor" href="#_113-5-ui-分流" aria-label="Permalink to &quot;113.5 UI 分流&quot;">​</a></h2><h3 id="概念解析-4" tabindex="-1">概念解析 <a class="header-anchor" href="#概念解析-4" aria-label="Permalink to &quot;概念解析&quot;">​</a></h3><p>PC 与 H5 的差异不是「字号小一点」，而是交互范式：PC 有 hover、右键、多列对照、快捷键；H5 有安全区、手势、44px 触控目标、单手操作。Element Plus 缩到手机或 Vant 拉到桌面，都会「能点但难用」。</p><table tabindex="0"><thead><tr><th>维度</th><th>Element Plus（PC）</th><th>Vant（H5）</th></tr></thead><tbody><tr><td>交互范式</td><td>鼠标、hover、高密度</td><td>触控、手势、单列卡片</td></tr><tr><td>按需体积</td><td>约 80KB gzip</td><td>约 40KB gzip</td></tr><tr><td>主题</td><td>CSS 变量 <code>--el-*</code></td><td>CSS 变量 <code>--van-*</code></td></tr><tr><td>典型组件</td><td>表格、树、级联、日期范围</td><td>底部弹层、步进器、轮播</td></tr></tbody></table><p>共享<strong>设计令牌</strong>，不共享组件实现：品牌色、圆角、字号、间距抽成 token，构建期分别生成 <code>--el-*</code> 与 <code>--van-*</code>。按需引进入口按端切换 resolver（<code>ElementPlusResolver</code> 或 <code>VantResolver</code>），两者互斥。</p><p>反例：共享组件 <code>DateRangePicker.vue</code> 原在 <code>ui-pc</code>，H5 直接 import「省事」。Element Plus 日期组件把整条依赖链拖进 H5，首屏 JS 从 240KB 涨到 520KB。正确做法是把取值与校验抽到 composable，两端各自渲染。</p><h3 id="应用实践-4" tabindex="-1">应用实践 <a class="header-anchor" href="#应用实践-4" aria-label="Permalink to &quot;应用实践&quot;">​</a></h3><ul><li>H5 底部操作栏加 <code>padding-bottom: env(safe-area-inset-bottom)</code>；PC 不需要。</li><li>PC 表格与筛选器在 H5 降级为「卡片流 + 底部筛选抽屉」。</li><li>主题按端产出：<code>element-theme.css</code> 与 <code>vant-theme.css</code>，token 源文件共享。</li></ul><h3 id="最佳实践-4" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践-4" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>✅ 两个 UI 库绝不同时全量注册，resolver 互斥，CI 检查产物 import。</li><li>✅ 移动端触控目标不小于 44×44px，PC 保留 hover/focus 可见态。</li><li>⚠️ 不要用 <code>display: none</code> 隐藏另一端页面来「复用」。</li></ul><hr><h2 id="_113-6-路由-状态-请求复用" tabindex="-1">113.6 路由 / 状态 / 请求复用 <a class="header-anchor" href="#_113-6-路由-状态-请求复用" aria-label="Permalink to &quot;113.6 路由 / 状态 / 请求复用&quot;">​</a></h2><h3 id="概念解析-5" tabindex="-1">概念解析 <a class="header-anchor" href="#概念解析-5" aria-label="Permalink to &quot;概念解析&quot;">​</a></h3><p>路由的复用单位是<strong>业务名</strong>，不是 path。同一业务 PC 叫 <code>/product/:id</code>，H5 叫 <code>/p/:id</code>；两端路由表各写一份，<code>name</code> 保持一致，埋点、跳转、权限只认 name。</p><p>降级是路由表的硬职责：PC 专属的批量导入在 H5 跳首页并提示，而不是 404；旧链接跨端打开时用另一端的表识别再重建路径（<code>/product/7</code> → <code>/p/7</code>），参数不能丢。完整实现见 <code>examples/113-03-dual-route-table.ts</code>：<code>buildPath</code> 按业务名生成路径并标记降级，<code>matchPath</code> 负责当前端匹配与旧链接重定向。</p><blockquote><p>运行方式：<code>npx tsx examples/113-03-dual-route-table.ts</code></p></blockquote><p>状态与请求「内核共享、表现分端」：Pinia 领域 store 共享，UI 状态分端；持久化走 <code>storage</code> 能力接口。请求用同一个 client，<code>baseURL</code> 由 mode 注入，统一错误结构与 traceId；H5 超时更短、重试更积极。结账、领券、下单必须带幂等键。</p><table tabindex="0"><thead><tr><th>关注点</th><th>共享</th><th>分端</th></tr></thead><tbody><tr><td>路由</td><td>业务 name、守卫</td><td>path、视图、降级表</td></tr><tr><td>状态</td><td>领域 store</td><td>UI 状态、持久化配额</td></tr><tr><td>请求</td><td>client、错误结构、幂等键</td><td>超时/重试策略</td></tr></tbody></table><h3 id="应用实践-5" tabindex="-1">应用实践 <a class="header-anchor" href="#应用实践-5" aria-label="Permalink to &quot;应用实践&quot;">​</a></h3><ul><li>守卫分三层：共享登录/权限、端能力守卫（PC-only 路由）、页面业务守卫。</li><li>路由懒加载按端分包，避免 H5 拉到 PC 页面代码。</li><li>埋点、AB、错误上报用业务名与模块名，不用路径。</li></ul><h3 id="最佳实践-5" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践-5" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>✅ 路由 <code>meta.ends</code> 声明支持端，构建期扫描生成降级清单。</li><li>✅ 旧链接重定向保留参数，目标必须能在当前端表里命中，防循环。</li><li>⚠️ H5 用 history 模式必须配服务端 fallback，否则深链 404。</li></ul><hr><h2 id="_113-7-pwa-接入" tabindex="-1">113.7 PWA 接入 <a class="header-anchor" href="#_113-7-pwa-接入" aria-label="Permalink to &quot;113.7 PWA 接入&quot;">​</a></h2><h3 id="概念解析-6" tabindex="-1">概念解析 <a class="header-anchor" href="#概念解析-6" aria-label="Permalink to &quot;概念解析&quot;">​</a></h3><p>PWA 四件套：<code>manifest</code>、SW、更新策略、离线兜底页。收益是复购用户把 H5 装到主屏，二次打开跳过地址栏，弱网仍可浏览。</p><p>缓存必须分层，不能一把梭 <code>CacheFirst</code>：</p><table tabindex="0"><thead><tr><th>资源</th><th>策略</th><th>理由</th></tr></thead><tbody><tr><td>App Shell</td><td>预缓存，版本化</td><td>离线可打开，随 SW 更新</td></tr><tr><td>商品图片</td><td><code>CacheFirst</code> + 上限</td><td>省流量，防爆存储</td></tr><tr><td>商品/库存 API</td><td><code>NetworkFirst</code> + 3s 超时</td><td>价格库存必须新鲜</td></tr><tr><td>导航请求</td><td>在线优先，失败回 <code>offline.html</code></td><td>不能钉死旧 HTML</td></tr><tr><td>POST/支付/下单</td><td><strong>绝不缓存</strong></td><td>重放会造成重复订单与资损</td></tr></tbody></table><p>更新默认 <code>registerType: &#39;prompt&#39;</code>：<code>skipWaiting</code> 会让新 SW 立即接管，旧页面可能加载新旧混合 chunk，造成白屏或样式错乱；用户在填地址/支付时被强制刷新会丢单。正确流程是「发现 → 提示 → 脏表单推迟 → 确认/保存后 <code>SKIP_WAITING</code> → <code>controllerchange</code> 只刷新一次」。状态机见 <code>examples/113-04-pwa-update-state-machine.ts</code>。</p><blockquote><p>运行方式：<code>npx tsx examples/113-04-pwa-update-state-machine.ts</code></p></blockquote><h3 id="应用实践-6" tabindex="-1">应用实践 <a class="header-anchor" href="#应用实践-6" aria-label="Permalink to &quot;应用实践&quot;">​</a></h3><ul><li><code>manifest</code> 含 <code>name/short_name/start_url/scope/display/theme_color</code>，图标给 192 与 512。</li><li>iOS Safari 不支持 <code>beforeinstallprompt</code>，引导「分享 → 添加到主屏幕」。</li><li>安装提示第二次访问或完成下单后再弹。</li></ul><h3 id="最佳实践-6" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践-6" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>✅ SW 只在 HTTPS（localhost 例外）生效，CI 用 Lighthouse 校验 manifest 与离线能力。</li><li>✅ SW 版本写入构建号，线上缓存问题一眼定位。</li><li>⚠️ 不缓存登录态、支付结果、个性化接口；设置过期与条目上限。</li></ul><hr><h2 id="_113-8-测试与-ci" tabindex="-1">113.8 测试与 CI <a class="header-anchor" href="#_113-8-测试与-ci" aria-label="Permalink to &quot;113.8 测试与 CI&quot;">​</a></h2><h3 id="概念解析-7" tabindex="-1">概念解析 <a class="header-anchor" href="#概念解析-7" aria-label="Permalink to &quot;概念解析&quot;">​</a></h3><p>多端测试重点不是「每页都写 E2E」，而是守住<strong>契约与产物</strong>：</p><table tabindex="0"><thead><tr><th>层级</th><th>测什么</th><th>触发</th></tr></thead><tbody><tr><td>单元</td><td>core 定价/优惠/状态机</td><td>每次提交</td></tr><tr><td>契约</td><td>两端 adapter 同构、路由 name 齐全</td><td>每次提交</td></tr><tr><td>组件</td><td>ui-pc / ui-h5 各自渲染</td><td>每次提交</td></tr><tr><td>构建</td><td>双端产物、入口、PWA、体积门禁</td><td>每次 PR</td></tr><tr><td>E2E</td><td>登录→商品→购物车→结账</td><td>合并前/夜间</td></tr></tbody></table><p>CI 用矩阵任务跑 <code>pc-prod</code> 与 <code>h5-prod</code>，随后执行产物校验与双视口 Playwright。体积门禁要卡两端首屏 vendor、CSS 总量、首屏图片、SW 体积、单 chunk 上限；任一项超预算即 fail，并输出对比上一版的增量，防止「每次涨一点，半年翻倍」。</p><h3 id="应用实践-7" tabindex="-1">应用实践 <a class="header-anchor" href="#应用实践-7" aria-label="Permalink to &quot;应用实践&quot;">​</a></h3><ul><li>PR 跑「类型检查 + 双端构建 + 契约 + 体积门禁」，控制在 10 分钟；全量 E2E 放夜间。</li><li>预览环境按端部署，产品验收两端各点一遍；测试数据保持一致。</li></ul><h3 id="最佳实践-7" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践-7" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>✅ 契约测试复用同一组断言跑两个 adapter，新增能力时两端同时红。</li><li>✅ 构建校验脚本与业务代码同仓同版本。</li><li>⚠️ 不要只构建 H5 就宣布通过——串端组件库问题只有双端构建能暴露。</li></ul><hr><h2 id="_113-9-自测题" tabindex="-1">113.9 自测题 <a class="header-anchor" href="#_113-9-自测题" aria-label="Permalink to &quot;113.9 自测题&quot;">​</a></h2><blockquote><p>先自己作答，再展开参考答案。</p></blockquote><details><summary><b>1. 为什么「一套代码」不等于 100% 复用？复用率怎么算？【基础】</b></summary><p>复用率是分层指标：<code>core</code>/<code>services</code> 追求 90%~100%，<code>ui</code> 通常 40%~70%，<code>adapters</code> 接近 0% 且是设计目的。强行让 UI 100% 会双 UI 库进包、两头难用；整体 70%~85% 已健康。</p></details><details><summary><b>2. 端判断为什么不能只依赖 UA？【基础】</b></summary><p>UA 可伪造、可被精简，触摸笔记本与横屏平板会误判。更可靠的是能力与形态：<code>maxTouchPoints &gt; 0</code> 且视口窄判 H5；触摸但宽视口归 PC。最终以能力探测（Web Share、原生桥）决定降级路径。</p></details><details><summary><b>3. PC 与 H5 为什么不应共用同一个 UI 组件库？按需引入解决什么？【基础】</b></summary><p>Element Plus 面向鼠标与高密度信息，Vant 面向触控与单列操作，尺寸、交互、无障碍目标不同。按需引入只解决体积，不解决范式；正确做法是组件分端、设计令牌共享。</p></details><details><summary><b>4. 构建期别名切换与运行时 \`if\` 分支差别在哪？【进阶】</b></summary><p>别名在打包阶段把 <code>@adapters</code> 指向另一套实现，另一端代码不进产物；运行时 <code>if</code> 只决定执行路径，两边 import 仍会打包。小逻辑可用运行时分支，UI 库、重依赖、端专属 SDK 必须构建期切换。</p></details><details><summary><b>5. 路由为什么按业务 name 而不是 path 做跨端契约？【进阶】</b></summary><p>path 是表现层细节，两端可完全不同；name 是业务唯一键，埋点、权限、跳转都认它。按 name 建表还能统一处理不支持路由降级与旧链接跨端重定向，避免 404 与参数丢失。</p></details><details><summary><b>6. PWA 更新为什么默认 prompt 而不是自动 skipWaiting？【进阶】</b></summary><p>自动 <code>skipWaiting</code> 让新 SW 立即接管，旧页面可能加载新旧混合 chunk，造成白屏或样式错乱；用户填表/支付时被强制刷新会丢数据。prompt 把更新时机交给用户，脏表单时推迟，保存或明确放弃后再激活。</p></details><details><summary><b>7. Service Worker 缓存如何分层？哪些绝不能缓存？【挑战】</b></summary><p>App Shell 预缓存并随版本更新；图片 <code>CacheFirst</code> 加上限；库存/价格 API 用 <code>NetworkFirst</code> 短超时；导航失败回离线页。POST、支付、下单、登录态、个性化接口绝不缓存，避免重放与资损；HTML 不能永久钉死。</p></details><details><summary><b>8. 海外电商 PC + H5/PWA 单仓：哪些必须共享，哪些必须分开？【挑战】</b></summary><p>共享定价/税费/汇率、购物车与优惠、订单状态机、库存规则、错误码、设计令牌、埋点事件名——影响金额与订单，必须唯一真相。分开 UI 组件与布局、path、adapter、构建入口与产物、PWA、交互状态。原则：出错会导致金额/库存/订单不一致就共享；只影响「看起来/点起来」就分端。</p></details><hr><h2 id="_113-10-本章避坑清单" tabindex="-1">113.10 本章避坑清单 <a class="header-anchor" href="#_113-10-本章避坑清单" aria-label="Permalink to &quot;113.10 本章避坑清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>坑点</th><th>现象</th><th>根因</th><th>正确姿势</th></tr></thead><tbody><tr><td>1</td><td>追求 UI 层 100% 复用</td><td>两端都难用，CSS 越写越多</td><td>桌面与触控是两套交互范式</td><td>组件分端，只共享设计令牌</td></tr><tr><td>2</td><td>H5 误引 PC 组件</td><td>H5 首屏 JS 翻倍，出现桌面弹层样式</td><td><code>ui-h5</code> import 了 <code>ui-pc</code></td><td>目录隔离 + <code>@ui</code> 别名 + CI 产物检查</td></tr><tr><td>3</td><td>两个 UI 库同时全量注册</td><td>包体暴涨，CSS 变量互相覆盖</td><td>两个 <code>app.use()</code> 都在入口</td><td>resolver 按端互斥，只注册一个库</td></tr><tr><td>4</td><td>用 UA 判断端</td><td>触摸笔记本/平板被当成 H5</td><td>UA 可伪造且信息不全</td><td>触摸能力 + 视口宽度 + 能力探测</td></tr><tr><td>5</td><td>用运行时 <code>if</code> 隔离重依赖</td><td>另一端代码仍在产物里</td><td><code>if</code> 不删除 import</td><td>构建期别名切换或独立入口</td></tr><tr><td>6</td><td><code>.env</code> 里写密钥</td><td>密钥随 <code>VITE_</code> 前缀打进客户端</td><td>误以为只有服务端能读</td><td>密钥走服务端/CI 注入</td></tr><tr><td>7</td><td>路由用 path 做跨端契约</td><td>换端后深链 404、埋点断裂</td><td>path 被当成业务标识</td><td>用业务 name 建表，path 只是表现</td></tr><tr><td>8</td><td>不支持的路由直接 404</td><td>H5 打开 PC 专属链接白屏</td><td>没有降级表</td><td><code>FALLBACK</code> 映射首页/提示页</td></tr><tr><td>9</td><td>PWA 自动 <code>skipWaiting</code></td><td>用户填表时被强制刷新，丢单</td><td>新 SW 立即接管旧页面</td><td><code>registerType: &#39;prompt&#39;</code> + 脏表单守卫</td></tr><tr><td>10</td><td>SW 缓存 POST/支付/HTML</td><td>重复下单、旧页面永不更新</td><td>缓存策略一刀切</td><td>只缓存 GET 静态资源，HTML 在线优先</td></tr></tbody></table><blockquote><p>心法：<strong>多端工程的核心不是「写一套代码」，而是「让不该共享的东西各归其位」</strong>。业务内核共享到字节级，交互表现分端到目录级，产物用构建矩阵隔开——做到这三点，复用率自然上去，包体与体验也不会互相拖累。靠 <code>if (isMobile)</code> 维持的多端，最终会变成两端都不敢改的泥潭。</p></blockquote>`,112)])])}const b=e(r,[["render",c]]);export{u as __pageData,b as default};
